use super::*;
fn dictionary(p:&mut Projection<'_,'_>,dictionary:&Dictionary)->Result<i64,ValueError>{let root=p.insert("generation_neural_dictionary",&[])?;let mut pending=vec![(root,dictionary)];while let Some((owner,d))=pending.pop(){p.checkpoint()?;for(i,(key,value))in d.iter().enumerate(){let(mut boolean,mut integer,mut decimal,mut string,mut child)=(Cell::Null,Cell::Null,Cell::Null,Cell::Null,Cell::Null);let kind=match value{NeuralValue::Atom(Atom::Null)=>"null",NeuralValue::Atom(Atom::Boolean(v))=>{boolean=Cell::Integer(i64::from(*v));"boolean"},NeuralValue::Atom(Atom::Integer(v))=>{integer=Cell::Integer(*v);"integer"},NeuralValue::Atom(Atom::Decimal(v))=>{decimal=Cell::Real(*v);"decimal"},NeuralValue::Atom(Atom::String(v))=>{string=Cell::Text(v);"string"},NeuralValue::Dictionary(v)=>{let id=p.insert("generation_neural_dictionary",&[])?;child=Cell::Integer(id);pending.push((id,v));"dictionary"}};let value_id=insert_ieee754(p,"generation_neural_value",&[Cell::Text(kind),boolean,integer,decimal,string,child],columns("generation_neural_value"))?;p.insert("generation_neural_entry",&[Cell::Integer(owner),Cell::Integer(ordinal(i)?),Cell::Text(key),Cell::Integer(value_id)])?;}}Ok(root)}
fn answer_scalar(p:&mut Projection<'_,'_>,value:&DslValue)->Result<i64,ValueError>{let(mut boolean,mut unsigned,mut integer,mut float,mut string,mut bytes)=(Cell::Null,Cell::Null,Cell::Null,Cell::Null,Cell::Null,Cell::Null);let unsigned_text;let kind=match value{DslValue::Null=>"null",DslValue::Bool(v)=>{boolean=Cell::Integer(i64::from(*v));"boolean"},DslValue::Number(Number::UInt(v))=>{unsigned_text=v.to_string();unsigned=Cell::Text(&unsigned_text);"unsigned"},DslValue::Number(Number::Int(v))=>{integer=Cell::Integer(*v);"integer"},DslValue::Number(Number::Float(v))=>{float=Cell::Real(*v);"float"},DslValue::String(v)=>{string=Cell::Text(v);"string"},DslValue::Bytes(v)=>{bytes=Cell::Blob(v);"bytes"},DslValue::Array(_)=>"array",DslValue::Object(_)=>"object"};insert_ieee754(p,"generation_value",&[Cell::Text(kind),boolean,unsigned,integer,float,string,bytes],columns("generation_value"))}
fn answer(p:&mut Projection<'_,'_>,value:&DslValue)->Result<i64,ValueError>{let root=answer_scalar(p,value)?;let mut pending=vec![(root,value)];while let Some((owner,value))=pending.pop(){p.checkpoint()?;match value{DslValue::Array(values)=>{for(i,value)in values.iter().enumerate(){let id=answer_scalar(p,value)?;p.insert("generation_array_element",&[Cell::Integer(owner),Cell::Integer(ordinal(i)?),Cell::Integer(id)])?;if matches!(value,DslValue::Array(_)|DslValue::Object(_)){pending.push((id,value));}}},DslValue::Object(values)=>{for(i,(key,value))in values.iter().enumerate(){let id=answer_scalar(p,value)?;p.insert("generation_object_member",&[Cell::Integer(owner),Cell::Integer(ordinal(i)?),Cell::Text(key),Cell::Integer(id)])?;if matches!(value,DslValue::Array(_)|DslValue::Object(_)){pending.push((id,value));}}},_=>{}}}Ok(root)}
fn tree(p:&mut Projection<'_,'_>,tree:&Tree)->Result<i64,ValueError>{let root=p.insert("generation_tree",&[])?;let mut pending=vec![(root,tree)];while let Some((owner,t))=pending.pop(){p.checkpoint()?;for(i,n)in t.neurons.iter().enumerate(){let parameters=dictionary(p,&n.params)?;let subtree=match &n.tree{None=>Cell::Null,Some(t)=>{let id=p.insert("generation_tree",&[])?;pending.push((id,t));Cell::Integer(id)}};p.insert("generation_tree_neuron",&[Cell::Integer(owner),Cell::Integer(ordinal(i)?),Cell::Text(&n.id),Cell::Text(&n.kind),Cell::Integer(parameters),subtree])?;}for(i,s)in t.synapses.iter().enumerate(){p.insert("generation_tree_synapse",&[Cell::Integer(owner),Cell::Integer(ordinal(i)?),Cell::Text(&s.id),Cell::Text(&s.from),Cell::Text(&s.to),Cell::Text(&s.from_port),Cell::Text(&s.to_port)])?;}}Ok(root)}
fn gui(p:&mut Projection<'_,'_>,ui:&FlowUi)->Result<i64,ValueError>{let camera=&ui.camera;let owner=insert_ieee754(p,"generation_gui",&[Cell::Real(camera.x),Cell::Real(camera.y),Cell::Real(camera.zoom)],columns("generation_gui"))?;for(i,(name,n))in ui.nodes.iter().enumerate(){let kind=match n.chrome{NodeChrome::Plain{..}=>"plain",NodeChrome::Slider{..}=>"slider",NodeChrome::Note{..}=>"note",NodeChrome::Image{..}=>"image",NodeChrome::Variable{..}=>"variable"};let id=insert_ieee754(p,"generation_gui_node",&[Cell::Integer(owner),Cell::Integer(ordinal(i)?),Cell::Text(name),Cell::Real(n.layout.x),Cell::Real(n.layout.y),Cell::Text(kind)],columns("generation_gui_node"))?;match &n.chrome{NodeChrome::Plain{preview}=>p.insert_key("generation_gui_plain",id,&[Cell::Integer(i64::from(*preview))])?,NodeChrome::Slider{label,min,max,step,value}=>insert_key_ieee754(p,"generation_gui_slider",id,&[Cell::Text(label),Cell::Real(*min),Cell::Real(*max),Cell::Real(*step),Cell::Real(*value)],columns("generation_gui_slider"))?,NodeChrome::Note{text}=>p.insert_key("generation_gui_note",id,&[Cell::Text(text)])?,NodeChrome::Image{src}=>p.insert_key("generation_gui_image",id,&[Cell::Text(src)])?,NodeChrome::Variable{name,schema}=>p.insert_key("generation_gui_variable",id,&[Cell::Text(name),Cell::Text(schema)])?}}
 for(i,v)in ui.previews.iter().enumerate(){let preview=dictionary(p,&v.preview)?;let(source_neuron,source_channel)=v.source.as_ref().map_or((Cell::Null,Cell::Null),|v|(Cell::Text(&v.neuron),Cell::Text(&v.channel)));let(x,y)=v.layout.as_ref().map_or((Cell::Null,Cell::Null),|v|(Cell::Real(v.x),Cell::Real(v.y)));let id=insert_ieee754(p,"generation_gui_preview",&[Cell::Integer(owner),Cell::Integer(ordinal(i)?),Cell::Text(&v.id),source_neuron,source_channel,Cell::Text(&v.mode),Cell::Integer(preview),x,y],columns("generation_gui_preview"))?;for(j,path)in v.expanded.iter().enumerate(){p.insert("generation_gui_expanded",&[Cell::Integer(id),Cell::Integer(ordinal(j)?),Cell::Text(path)])?;}}Ok(owner)}
/// 📤️ Borrows the actual domain fields and emits only explicitly authored entity rows.
pub fn project(host:&FlowHostSnapshot,generation:&GenerationPlayRoot,sql:&str,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{let mut p=Projection::new(sql,c)?;p.check_rows(2)?;insert_key_ieee754(&mut p,"generation_host",1,&[Cell::Text(&host.schema),Cell::Real(host.camera.x),Cell::Real(host.camera.y),Cell::Real(host.camera.zoom)],columns("generation_host"))?;p.insert_key("generation_document",1,&[Cell::Integer(1),generation.selected_generation_id.as_deref().map_or(Cell::Null,Cell::Text),generation.preview_text.as_deref().map_or(Cell::Null,Cell::Text)])?;
 for(i,w)in host.widgets.iter().enumerate(){let(kind,name)=match w{Widget::Neuron{id,..}=>("neuron",id),Widget::InputSlider{id,..}=>("input_slider",id),Widget::InputNote{id,..}=>("input_note",id),Widget::InputImage{id,..}=>("input_image",id),Widget::Variable{id,..}=>("variable",id),Widget::OutputPreview{id,..}=>("output_preview",id),Widget::OutputAction{id,..}=>("output_action",id),Widget::OutputExport{id,..}=>("output_export",id),Widget::Cluster{id,..}=>("cluster",id)};let id=p.insert("generation_widget",&[Cell::Integer(1),Cell::Integer(ordinal(i)?),Cell::Text(name),Cell::Text(kind)])?;match w{Widget::Neuron{neuron_kind,params,input_ports,output_ports,preview,..}=>{let parameters=dictionary(&mut p,params)?;p.insert_key("generation_neuron_widget",id,&[Cell::Text(neuron_kind),Cell::Integer(parameters),Cell::Integer(i64::from(*preview))])?;for(direction,ports)in[("input",input_ports),("output",output_ports)]{for(j,name)in ports.iter().enumerate(){p.insert("generation_widget_port",&[Cell::Integer(id),Cell::Text(direction),Cell::Integer(ordinal(j)?),Cell::Text(name)])?;}}},Widget::InputSlider{label,value,min,max,step,..}=>insert_key_ieee754(&mut p,"generation_slider_widget",id,&[Cell::Text(label),Cell::Real(*value),Cell::Real(*min),Cell::Real(*max),Cell::Real(*step)],columns("generation_slider_widget"))?,Widget::InputNote{text,..}=>p.insert_key("generation_note_widget",id,&[Cell::Text(text)])?,Widget::InputImage{src,..}=>p.insert_key("generation_image_widget",id,&[Cell::Text(src)])?,Widget::Variable{name,schema,..}=>p.insert_key("generation_variable_widget",id,&[Cell::Text(name),Cell::Text(schema)])?,Widget::OutputPreview{preview,expanded,..}=>{let preview=dictionary(&mut p,preview)?;p.insert_key("generation_preview_widget",id,&[Cell::Integer(preview)])?;for(j,path)in expanded.iter().enumerate(){p.insert("generation_widget_expanded",&[Cell::Integer(id),Cell::Integer(ordinal(j)?),Cell::Text(path)])?;}},Widget::OutputAction{action,..}=>p.insert_key("generation_action_widget",id,&[Cell::Text(action)])?,Widget::OutputExport{format,..}=>p.insert_key("generation_export_widget",id,&[Cell::Text(format)])?,Widget::Cluster{name,tree:t,flow,..}=>{let tree=tree(&mut p,t)?;let gui=gui(&mut p,flow)?;p.insert_key("generation_cluster_widget",id,&[Cell::Text(name),Cell::Integer(tree),Cell::Integer(gui)])?;}}}
 for(i,s)in host.synapses.iter().enumerate(){p.insert("generation_host_synapse",&[Cell::Integer(1),Cell::Integer(ordinal(i)?),Cell::Text(&s.id),Cell::Text(&s.from),Cell::Text(&s.to),Cell::Text(&s.from_port),Cell::Text(&s.to_port)])?;}for(i,(name,v))in host.layout.iter().enumerate(){insert_ieee754(&mut p,"generation_host_layout",&[Cell::Integer(1),Cell::Integer(ordinal(i)?),Cell::Text(name),Cell::Real(v.x),Cell::Real(v.y)],columns("generation_host_layout"))?;}
 for(i,g)in generation.generations.iter().enumerate(){let id=p.insert("generation_preset",&[Cell::Integer(1),Cell::Integer(ordinal(i)?),Cell::Text(&g.id),Cell::Text(&g.name)])?;p.check_rows(g.values.len())?;p.checkpoint()?;for(j,(key,value))in g.values.iter().enumerate(){let value=answer(&mut p,value)?;p.insert("generation_answer",&[Cell::Integer(id),Cell::Integer(ordinal(j)?),Cell::Text(key),Cell::Integer(value)])?;}}p.finish()}
